import java.io.*;
import java.util.*;

class Solution {
    public int maxSideLength(int[][] mat, int threshold) {
        int m = mat.length;
        int n = mat[0].length;
        long[][] ps = new long[m + 1][n + 1];

        for (int i = 0; i < m; i++) {
            long rowSum = 0;
            for (int j = 0; j < n; j++) {
                rowSum += mat[i][j];
                ps[i + 1][j + 1] = ps[i][j + 1] + rowSum;
            }
        }

        int lo = 0, hi = Math.min(m, n);
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            boolean ok = true;
            if (mid > 0) {
                ok = false;
                outer:
                for (int i = mid; i <= m; i++) {
                    for (int j = mid; j <= n; j++) {
                        long sum = ps[i][j] - ps[i - mid][j]
                                 - ps[i][j - mid] + ps[i - mid][j - mid];
                        if (sum <= threshold) {
                            ok = true;
                            break outer;
                        }
                    }
                }
            }
            if (ok) lo = mid + 1;
            else hi = mid - 1;
        }
        return hi;
    }
}

