typedef struct {
    char* s;
    int pos;
    int len;
} Tok;

static void skipWS(Tok* t) {
    while (t->pos < t->len &&
           (t->s[t->pos] == ' ' || t->s[t->pos] == ',' ||
            t->s[t->pos] == '\t' || t->s[t->pos] == '\n' ||
            t->s[t->pos] == '\r')) {
        t->pos++;
    }
}

static char* nextToken(Tok* t) {
    skipWS(t);
    if (t->pos >= t->len) return NULL;
    int start = t->pos;
    if (t->s[t->pos] == '[') {
        int depth = 0;
        while (t->pos < t->len) {
            char c = t->s[t->pos++];
            if (c == '[') depth++;
            else if (c == ']') {
                depth--;
                if (depth == 0) break;
            }
        }
    } else {
        while (t->pos < t->len && t->s[t->pos] != ',' &&
               t->s[t->pos] != ']' && t->s[t->pos] != '[') {
            t->pos++;
        }
    }
    int n = t->pos - start;
    char* out = (char*)malloc((size_t)n + 1);
    memcpy(out, t->s + start, (size_t)n);
    out[n] = '\0';
    return out;
}

static int parseInt(Tok* t) {
    char* tok = nextToken(t);
    int v = atoi(tok);
    free(tok);
    return v;
}

static int* parseIntArray(Tok* t, int* outSize) {
    char* tok = nextToken(t);
    if (!tok || strcmp(tok, "[]") == 0) {
        free(tok);
        *outSize = 0;
        return NULL;
    }
    int len = (int)strlen(tok);
    char* inner = (char*)malloc((size_t)len - 1);
    memcpy(inner, tok + 1, (size_t)len - 2);
    inner[len - 2] = '\0';
    free(tok);

    int count = 1;
    for (int i = 0; inner[i]; ++i) if (inner[i] == ',') count++;
    int* a = (int*)malloc((size_t)count * sizeof(int));

    Tok t2 = { inner, 0, (int)strlen(inner) };
    for (int i = 0; i < count; ++i) a[i] = parseInt(&t2);

    free(inner);
    *outSize = count;
    return a;
}

static int** parseMatrix(Tok* t, int* rows, int** cols) {
    char* tok = nextToken(t);
    if (!tok || strcmp(tok, "[]") == 0) {
        free(tok);
        *rows = 0;
        *cols = NULL;
        return NULL;
    }
    int len = (int)strlen(tok);
    char* inner = (char*)malloc((size_t)len - 1);
    memcpy(inner, tok + 1, (size_t)len - 2);
    inner[len - 2] = '\0';
    free(tok);

    int r = 0, depth = 0;
    for (int i = 0; inner[i]; ++i) {
        if (inner[i] == '[') {
            if (depth == 0) r++;
            depth++;
        } else if (inner[i] == ']') {
            depth--;
        }
    }

    int** mat = (int**)malloc((size_t)r * sizeof(int*));
    int* cs = (int*)malloc((size_t)r * sizeof(int));

    Tok t2 = { inner, 0, (int)strlen(inner) };
    for (int i = 0; i < r; ++i) mat[i] = parseIntArray(&t2, &cs[i]);

    free(inner);
    *rows = r;
    *cols = cs;
    return mat;
}

int maxSideLength(int** mat, int matSize, int* matColSize, int threshold) {
    int m = matSize, n = matColSize[0];
    long long* ps = (long long*)calloc((size_t)(m + 1) * (n + 1), sizeof(long long));
    if (!ps) return 0;

    #define PS(i,j) ps[(size_t)(i) * (n + 1) + (j)]
    for (int i = 0; i < m; ++i) {
        long long rowSum = 0;
        for (int j = 0; j < n; ++j) {
            rowSum += mat[i][j];
            PS(i + 1, j + 1) = PS(i, j + 1) + rowSum;
        }
    }

    int lo = 0, hi = m < n ? m : n;
    while (lo <= hi) {
        int k = lo + (hi - lo) / 2;
        int ok = (k == 0);
        if (!ok) {
            for (int i = k; i <= m && !ok; ++i) {
                for (int j = k; j <= n; ++j) {
                    long long sum = PS(i,j) - PS(i-k,j) - PS(i,j-k) + PS(i-k,j-k);
                    if (sum <= threshold) {
                        ok = 1;
                        break;
                    }
                }
            }
        }
        if (ok) lo = k + 1;
        else hi = k - 1;
    }

    free(ps);
    return hi;
    #undef PS
}

